package main
import ("log";"net/http";"os")
func main(){p:=os.Getenv("PORT");if p==""{p="10000"};http.HandleFunc("/",func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","text/html; charset=utf-8");w.Write([]byte(html))});log.Println(p);http.ListenAndServe(":"+p,nil)}
const html=
"<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width'><div><select id=m><option value=11>Nov<option value=12>Des</select><input id=y value=2026><button onclick=R()>Sawa</button><div style='display:flex'><div style='flex:1;background:#2e7d32;color:#fff'>MAPATO<br><span id=a>0</span></div><div style='flex:1;background:#c00;color:#fff'>MATUMIZI<br><span id=b>0</span></div><div style='flex:1;background:#1565c0;color:#fff'>SALIO<br><span id=c>0</span></div></div><div>Wanachama <button onclick=W()>+ Mpya</button><div id=wl></div></div><div><select id=sw></select><select id=sa><option value=hisa>Hisa<option value=ada>Ada ya Mwezi<option value=faini_ada>Riba ya Ada<option value=mkopo_toka>Mkopo<option value=marejesho>Rejesho la Mwezi<option value=faini_marejesho>Riba ya Rejesho<option value=michango_mingine>Michango Mingine</select><input id=kv><button onclick=M()>Hifadhi</button></div><div><button onclick=E()>Pakua Excel</button><div id=hi></div></div></div><script>D=JSON.parse(localStorage.v8||'null')||{w:[],m:[]};function S(){localStorage.v8=JSON.stringify(D);R()}function W(){j=prompt('Jina:');if(j){D.w.push({j:j});S()}}function M(){w=(sw.value||'').trim();a=sa.value;k=+kv.value;if(!w||!k)return alert('Jaza');D.m.push({w:w,a:a,k:k,mm:+m.value,yy:+y.value});if(a=='mkopo_toka'){f=Math.round(k*0.05);D.m.push({w:w,a:'fomu',k:f,mm:+m.value,yy:+y.value})}kv.value='';S()}function R(){mm=+m.value;yy=+y.value;mi=D.m.filter(x=>x.mm==mm&&x.yy==yy);mp=0;mt=0;mi.forEach(t=>{if(['hisa','ada','faini_ada','fomu','marejesho','faini_marejesho','michango_mingine'].includes(t.a))mp+=t.k;if(t.a=='mkopo_toka')mt+=t.k});a.innerText=mp;b.innerText=mt;c.innerText=mp-mt;wl.innerHTML=sw.innerHTML='';if(!D.w.length)wl.innerHTML='-';D.w.forEach((x,i)=>{wl.innerHTML+=x.j+' <button onclick=\"D.w.splice('+i+',1);S()\">X</button><br>';sw.innerHTML+='<option>'+x.j+'</option>'});hi.innerHTML='';mi.slice().reverse().forEach((t,idx)=>{let i=D.m.length-1-idx;hi.innerHTML+=t.w+'-'+t.a+'-'+t.k+' <button onclick=\"Ed('+i+')\">E</button> <button onclick=\"D.m.splice('+i+',1);S()\">X</button><br>'})}function Ed(i){t=D.m[i];v=prompt('Kiasi:',t.k);if(v&&+v>0){t.k=+v;S()}}function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;')}function Rr(r){s='<Row>';r.forEach(v=>{s+='<Cell><Data>'+esc(v)+'</Data></Cell>'});return s+'</Row>'}function E(){x=D.m.filter(t=>t.mm==+m.value&&t.yy==+y.value);if(!x.length)return alert('Hakuna');r1=[['Jina','Ada ya Mwezi','Riba ya Ada']];r2=[['Jina','Mkopo Uliochukuliwa','Fomu','Rejesho la Mwezi','Riba ya Rejesho','Baki']];r3=[['Jina','Hisa']];r4=[['Jina','Michango Mingine']];am={};ar={};dm={};hm={};rm={};rr={};me={};x.forEach(t=>{let w=(t.w||'').trim();if(am[w]==null){am[w]=0;ar[w]=0;hm[w]=0;me[w]=0;rm[w]=0;rr[w]=0}if(!dm[w])dm[w]={c:0,f:0};if(t.a=='ada')am[w]+=t.k;if(t.a=='faini_ada')ar[w]+=t.k;if(t.a=='mkopo_toka')dm[w].c+=t.k;if(t.a=='fomu')dm[w].f+=t.k;if(t.a=='hisa')hm[w]+=t.k;if(t.a=='marejesho')rm[w]+=t.k;if(t.a=='faini_marejesho')rr[w]+=t.k;if(t.a=='michango_mingine')me[w]+=t.k});for(j in am)r1.push([j,am[j],ar[j]]);for(j in dm){let c=dm[j].c,f=dm[j].f,r=rm[j]||0,fr=rr[j]||0,b=c-r;r2.push([j,c,f,r,fr,b])}for(j in hm)r3.push([j,hm[j]]);for(j in me)r4.push([j,me[j]]);function Sh(n,r){h='<Worksheet ss:Name=\"'+n+'\"><Table>';r.forEach(t=>{h+=Rr(t)});return h+'</Table></Worksheet>'}xml='<Workbook xmlns:ss=\"urn:schemas-microsoft-com:office:spreadsheet\">'+Sh('1-Ada ya Mwezi',r1)+Sh('2-Mkopo',r2)+Sh('3-Hisa',r3)+Sh('4-Michango Mingine',r4)+'</Workbook>';b=new Blob([xml]);u=URL.createObjectURL(b);z=document.createElement('a');z.href=u;z.download='Uwashusema.xls';document.body.appendChild(z);z.click()}m.value=11;R();</script>"
